function setLoading(on){$('#loading').classList.toggle('hidden',!on)}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.classList.toggle('error-toast',error);el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2800)}
function modal(html){$('#modalBody').innerHTML=html;$('#modal').classList.remove('hidden');setTimeout(()=>$('#modalBody input, #modalBody select')?.focus(),30)}
function closeModal(){if($('#modalBody').dataset.busy==='1')return;$('#modal').classList.add('hidden');$('#modalBody').innerHTML=''}
function fail(e){console.error(e);toast(errorText(e),true)}
function errorText(e){const m=e?.message||String(e||'เกิดข้อผิดพลาด');const map={AUTH_REQUIRED:'กรุณาเข้าสู่ระบบ',ROLE_NOT_ALLOWED:'บัญชีนี้ไม่มีสิทธิ์ทำรายการ',PLATFORM_ADMIN_REQUIRED:'บัญชีนี้ไม่มีสิทธิ์จัดการลูกค้า',COMPANY_INACTIVE:'บริษัทถูกระงับหรือหมดอายุ กรุณาติดต่อผู้ดูแล FlowStock',COMPANY_NOT_FOUND:'ไม่พบรหัสบริษัท หรือบริษัทยังไม่เปิดใช้งาน',COMPANY_CODE_EXISTS:'รหัสบริษัทนี้ถูกใช้แล้ว',COMPANY_CODE_REQUIRED:'กรุณาระบุรหัสบริษัท',ACCESS_REQUEST_ALREADY_PENDING:'บัญชีนี้มีคำขอของบริษัทอื่นที่กำลังรออนุมัติ',INVALID_OR_EXPIRED_ONBOARDING_CODE:'รหัสเปิดบริษัทไม่ถูกต้อง หมดอายุ หรือถูกใช้แล้ว',USER_LIMIT_REACHED:'จำนวนผู้ใช้ถึงขีดจำกัดแพ็กเกจแล้ว',INVALID_POD_FILE:'รองรับ POD แบบ PDF, JPG หรือ PNG ขนาดไม่เกิน 10 MB',POD_OBJECT_NOT_FOUND:'ไม่พบไฟล์ POD ที่อัปโหลด',INVALID_CUSTOMER:'ไม่พบลูกค้า',INVALID_PRODUCT:'ไม่พบสินค้า',INVALID_WAREHOUSE:'ไม่พบคลัง',INSUFFICIENT_STOCK:'Stock ไม่เพียงพอ',ORDER_NOT_ISSUABLE:'Order นี้ไม่อยู่ในสถานะที่จ่ายสินค้าได้',ORDER_NOT_READY_FOR_DELIVERY:'Order ยังจ่ายสินค้าไม่ครบ',VEHICLE_TIME_CONFLICT:'รถคันนี้มีงานซ้อนในช่วงเวลาที่เลือก',VARIANCE_REASON_REQUIRED:'กรุณาระบุเหตุผลส่วนต่าง',DELIVERY_VARIANCE_REASON_REQUIRED:'กรุณาระบุเหตุผลที่ลูกค้ารับไม่ครบ'};return map[m]||m}
function badge(s){const c=['DELIVERED','COMPLETED','POSTED','FINAL','ACTIVE'].includes(s)?'ok':['CONFIRMED','PARTIAL_ISSUE','ESTIMATED','IN_TRANSIT','TRIAL','DEMO'].includes(s)?'warn':['WAITING_LOGISTICS','IN_DELIVERY','PLANNED'].includes(s)?'blue':['CANCELLED','SUSPENDED','EXPIRED','INACTIVE'].includes(s)?'danger':'';return `<span class="badge ${c}">${esc(statusThai[s]||s||'-')}</span>`}
function empty(text='ไม่พบข้อมูล'){return `<div class="empty">${esc(text)}</div>`}
function head(title,sub='',actions=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`}
function cards(items){return `<div class="cards">${items.map(x=>`<div class="card"><div class="label">${esc(x[0])}</div><div class="value">${x[1]}</div><div class="hint">${esc(x[2]||'')}</div></div>`).join('')}</div>`}
function table(headers,rows){if(!rows.length)return empty();return `<div class="table-wrap"><table><thead><tr>${headers.map((h,i)=>`<th class="sortable" data-col="${i}">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`}
function wireSort(){ $$('#page th.sortable').forEach(th=>th.onclick=()=>{const body=th.closest('table').tBodies[0],i=+th.dataset.col,asc=th.dataset.asc!=='1';[...body.rows].sort((a,b)=>{const x=a.cells[i]?.dataset.sort??a.cells[i]?.innerText??'',y=b.cells[i]?.dataset.sort??b.cells[i]?.innerText??'';return (Number.isFinite(+x)&&Number.isFinite(+y)?+x-+y:String(x).localeCompare(String(y),'th'))*(asc?1:-1)}).forEach(r=>body.appendChild(r));th.dataset.asc=asc?'1':'0'})}

async function init(){
  bindShell();
  const {data:{session}}=await db.auth.getSession();
  if(session)await startApp(session);else showLogin();
  db.auth.onAuthStateChange(async(event,session)=>{if(event==='SIGNED_OUT')showLogin();if(event==='SIGNED_IN'&&session&&!state.session)await startApp(session);if(event==='PASSWORD_RECOVERY')passwordRecoveryModal()});
}
function bindShell(){
  $('#loginForm').addEventListener('submit',login);$('#signupForm').addEventListener('submit',signup);$('#logoutBtn').onclick=()=>db.auth.signOut();
  $('#forgotBtn').onclick=forgotPassword;
  $('#signupBtn').onclick=()=>toggleSignup(true);$('#backLoginBtn').onclick=()=>toggleSignup(false);$('#pendingLogoutBtn').onclick=()=>db.auth.signOut();
  $('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#modalClose').onclick=closeModal;
  $('#modal').onclick=e=>{if(e.target.id==='modal')closeModal()};
  $('#refreshBtn').onclick=async()=>{await loadData();render();toast('อัปเดตข้อมูลแล้ว')};
  document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
}
function toggleSignup(on){$('#loginForm').classList.toggle('hidden',on);$('#signupBtn').classList.toggle('hidden',on);$('#signupForm').classList.toggle('hidden',!on);$('#pendingView').classList.add('hidden');$('#signupError').textContent=''}
async function login(e){e.preventDefault();$('#loginError').textContent='';setLoading(true);const {error}=await db.auth.signInWithPassword({email:$('#email').value.trim(),password:$('#password').value});setLoading(false);if(error)$('#loginError').textContent='อีเมลหรือรหัสผ่านไม่ถูกต้อง'}
async function submitAccess(){const onboarding=$('#signupOnboarding').value.trim();if(onboarding)return db.rpc('claim_tenant_admin',{p_onboarding_code:onboarding,p_full_name:$('#signupName').value.trim(),p_employee_code:$('#signupEmployee').value.trim()||null});return db.rpc('request_access',{p_full_name:$('#signupName').value.trim(),p_employee_code:$('#signupEmployee').value.trim(),p_requested_role:$('#signupRole').value,p_company_code:$('#signupCompany').value.trim()})}
async function signup(e){e.preventDefault();$('#signupError').textContent='';setLoading(true);if(state.requestOnly){const {data,error}=await submitAccess();setLoading(false);if(error)return $('#signupError').textContent=errorText(error);if(data?.status==='ACTIVE')return location.reload();showPending();return}const email=$('#signupEmail').value.trim(),password=$('#signupPassword').value;const {data,error}=await db.auth.signUp({email,password});if(error){setLoading(false);$('#signupError').textContent=errorText(error);return}if(data.session){const {data:access,error:re}=await submitAccess();if(re){setLoading(false);$('#signupError').textContent=errorText(re);return}if(access?.status==='ACTIVE')return location.reload();showPending()}else{$('#signupError').textContent='กรุณายืนยันอีเมล แล้ว Login จากนั้นกรอกข้อมูลบริษัทอีกครั้ง'}setLoading(false)}
function showLogin(){state.session=null;state.profile=null;state.company=null;state.isPlatformAdmin=false;state.requestOnly=false;state.page='dashboard';setLoading(false);$('#signupPassword').closest('label').classList.remove('hidden');$('#signupEmail').closest('label').classList.remove('hidden');$('#signupForm button[type="submit"]').textContent='ส่งคำขอเปิดใช้งาน';$('#shell').classList.add('hidden');$('#authView').classList.remove('hidden');toggleSignup(false)}
function showPending(){setLoading(false);$('#shell').classList.add('hidden');$('#authView').classList.remove('hidden');$('#loginForm').classList.add('hidden');$('#signupForm').classList.add('hidden');$('#signupBtn').classList.add('hidden');$('#pendingView').classList.remove('hidden')}
async function startApp(session){
  setLoading(true);state.session=session;
  const {data,error}=await db.rpc('get_my_context');
  if(error){throw error}
  if(!data){const {data:req}=await db.from('access_requests').select('status').eq('user_id',session.user.id).eq('status','PENDING').maybeSingle();if(req){showPending();return}state.requestOnly=true;toggleSignup(true);$('#signupEmail').value=session.user.email||'';$('#signupEmail').closest('label').classList.add('hidden');$('#signupPassword').closest('label').classList.add('hidden');$('#signupForm button[type="submit"]').textContent='ส่งคำขอเปิดใช้งาน';setLoading(false);return}
  if(!data.active){showPending();return}
  state.profile=data;state.company=data.company;state.isPlatformAdmin=Boolean(data.is_platform_admin);$('#companyName').textContent=data.company?.name||'FlowStock';$('#roleName').textContent=roleThai[data.app_role]||data.app_role;$('#sideUser').textContent=`${data.full_name} • ${data.employee_code||''}`;
  if(!data.active||!data.company?.active||['SUSPENDED','EXPIRED'].includes(data.company?.subscription_status)||(data.company?.subscription_status==='TRIAL'&&data.company.trial_ends_at&&new Date(data.company.trial_ends_at)<=new Date())){state.page='inactive';renderNav();$('#authView').classList.add('hidden');$('#shell').classList.remove('hidden');setLoading(false);render();return}
  renderNav();await loadData();$('#authView').classList.add('hidden');$('#shell').classList.remove('hidden');setLoading(false);render();
}
function renderNav(){const menus=state.page==='inactive'?[]:[...(roleMenus[state.profile.app_role]||roleMenus.SALES)];if(state.isPlatformAdmin)menus.push(['commercial','◆','Commercial Control']);$('#nav').innerHTML=menus.map(m=>`<button class="nav-btn ${state.page===m[0]?'active':''}" data-page="${m[0]}"><span class="nav-icon">${m[1]}</span>${m[2]}</button>`).join('');$$('.nav-btn').forEach(b=>b.onclick=()=>go(b.dataset.page))}
function go(page){state.page=page;state.search='';if(page!=='profit')state.reportCustomer='ALL';renderNav();$('#sidebar').classList.remove('open');render()}

async function loadData(){
  setLoading(true);
  const queries={
    customers:db.from('customers').select('*').order('code'),products:db.from('products').select('*').order('code'),warehouses:db.from('warehouses').select('*').order('code'),suppliers:db.from('suppliers').select('*').order('code'),vehicles:db.from('vehicles').select('*').order('code'),drivers:db.from('drivers').select('*').order('code'),
    balances:db.from('stock_balances').select('*'),movements:db.from('stock_movements').select('*').order('created_at',{ascending:false}).limit(300),
    orders:db.from('orders').select('*').order('created_at',{ascending:false}),orderLines:db.from('order_lines').select('*'),
    receipts:db.from('goods_receipts').select('*').order('receipt_date',{ascending:false}),transfers:db.from('transfers').select('*').order('transfer_no',{ascending:false}),transferLines:db.from('transfer_lines').select('*'),
    trips:db.from('delivery_trips').select('*').order('planned_start',{ascending:false}),tripLines:db.from('delivery_trip_lines').select('*'),deliveryDocs:db.from('delivery_documents').select('*').order('created_at',{ascending:false}),invoices:db.from('invoices').select('*').order('invoice_date',{ascending:false}),invoiceOrders:db.from('invoice_orders').select('*'),
    costs:db.from('monthly_product_costs').select('*').order('cost_month',{ascending:false}),counts:db.from('stock_counts').select('*').order('snapshot_at',{ascending:false}),countLines:db.from('stock_count_lines').select('*'),periods:db.from('period_closes').select('*').order('period_month',{ascending:false}),settings:db.from('app_settings').select('*'),accessRequests:db.from('access_requests').select('*').order('requested_at',{ascending:false}),users:can('ADMIN')?db.rpc('admin_list_users'):Promise.resolve({data:[],error:null}),audit:db.from('audit_logs').select('*').order('created_at',{ascending:false}).limit(200),tenants:state.isPlatformAdmin?db.rpc('platform_list_companies'):Promise.resolve({data:[],error:null})
  };
  const entries=Object.entries(queries),results=await Promise.all(entries.map(x=>x[1]));
  results.forEach((r,i)=>{if(r.error){if(['audit','accessRequests'].includes(entries[i][0])&&!can('ADMIN','OWNER'))state.data[entries[i][0]]=[];else throw r.error}else state.data[entries[i][0]]=r.data||[]});
  setLoading(false);
}

function render(){
  const pages={dashboard:dashboardPage,executive:dashboardPage,orders:ordersPage,warehouse:warehousePage,stock:stockPage,counts:countsPage,transfers:transfersPage,delivery:deliveryPage,profit:profitPage,customer360:customer360Page,stockhealth:stockHealthPage,deliveryperformance:deliveryPerformancePage,costvariance:costVariancePage,reports:reportsPage,customers:customersPage,masters:mastersPage,users:usersPage,settings:settingsPage,audit:auditPage,commercial:commercialPage,inactive:inactivePage};
  $('#page').innerHTML=(pages[state.page]||dashboardPage)();wireSort();wirePage();
}
function wirePage(){
  $$('[data-action]').forEach(b=>b.onclick=()=>{const action=actions[b.dataset.action];if(!action)return toast(`ปุ่ม ${b.dataset.action} ยังไม่พร้อมใช้งาน`,true);action(b.dataset.id)});
  $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));
  $$('[data-profit-view]').forEach(b=>b.onclick=()=>{state.profitView=b.dataset.profitView;render()});
  const search=$('#pageSearch');if(search){search.value=state.search;search.oninput=()=>{state.search=search.value.toLowerCase();render()}}
  const year=$('#reportYear');if(year){year.value=state.reportYear;year.onchange=()=>{state.reportYear=year.value;render()}}
  const wh=$('#reportWarehouse');if(wh){wh.value=state.reportWarehouse;wh.onchange=()=>{state.reportWarehouse=wh.value;render()}}
  const customer=$('#reportCustomer');if(customer){customer.value=state.reportCustomer;customer.onchange=()=>{state.reportCustomer=customer.value;render()}}
}
const byId=(list,id)=>state.data[list]?.find(x=>x.id===id);
const customerName=id=>byId('customers',id)?.name||'-';const product=id=>byId('products',id)||{};const warehouse=id=>byId('warehouses',id)||{};
const orderLines=id=>state.data.orderLines.filter(x=>x.order_id===id);const tripLines=id=>state.data.tripLines.filter(x=>x.trip_id===id);const transferLine=id=>state.data.transferLines.find(x=>x.transfer_id===id);
const stockAvailable=(pid,wid)=>{const b=state.data.balances.find(x=>x.product_id===pid&&x.warehouse_id===wid);return Number(b?.on_hand||0)-Number(b?.allocated||0)};

const invoiceGp=i=>Number(i.revenue||0)-Number(i.product_cost||0)-Number(i.freight_cost||0)-Number(i.other_cost||0);
const compactMoney=n=>{const v=Number(n||0);return Math.abs(v)>=1000000?`฿${(v/1000000).toFixed(2)}m`:Math.abs(v)>=1000?`฿${(v/1000).toFixed(1)}k`:money(v)};
const invoiceOrderId=id=>state.data.invoiceOrders?.find(x=>x.invoice_id===id)?.order_id;
function analyticsYears(){const years=new Set([String(new Date().getFullYear()),...(state.data.invoices||[]).map(x=>String(new Date(x.invoice_date).getFullYear())).filter(x=>x!=='NaN')]);return [...years].sort((a,b)=>b-a)}
function analyticsInvoices(){return (state.data.invoices||[]).filter(i=>{const y=String(new Date(i.invoice_date).getFullYear());if(y!==state.reportYear)return false;if(state.reportCustomer!=='ALL'&&i.customer_id!==state.reportCustomer)return false;if(state.reportWarehouse==='ALL')return true;const oid=invoiceOrderId(i.id);return oid&&orderLines(oid).some(l=>l.warehouse_id===state.reportWarehouse)})}
function analyticsTrips(){return (state.data.trips||[]).filter(t=>{if(String(new Date(t.planned_start).getFullYear())!==state.reportYear)return false;if(state.reportWarehouse==='ALL')return true;return orderLines(t.order_id).some(l=>l.warehouse_id===state.reportWarehouse)})}
function analyticsBalances(){return (state.data.balances||[]).filter(b=>state.reportWarehouse==='ALL'||b.warehouse_id===state.reportWarehouse)}
function analyticsFilters({year=true,warehouse=true,customer=false}={}){return `${year?`<select id="reportYear" aria-label="ปี">${analyticsYears().map(y=>`<option value="${y}">ปี ${y}</option>`).join('')}</select>`:''}${warehouse?`<select id="reportWarehouse" aria-label="คลัง"><option value="ALL">ทุกคลัง</option>${state.data.warehouses.map(w=>`<option value="${w.id}">${esc(w.code)} • ${esc(w.name)}</option>`).join('')}</select>`:''}${customer?`<select id="reportCustomer" aria-label="ลูกค้า"><option value="ALL">ลูกค้าทั้งหมด</option>${state.data.customers.filter(x=>x.active!==false).map(x=>`<option value="${x.id}">${esc(x.code)} • ${esc(x.name)}</option>`).join('')}</select>`:''}`}
function monthlySeries(invoices=analyticsInvoices()){const months=Array.from({length:12},(_,i)=>({label:new Intl.DateTimeFormat('th-TH',{month:'short'}).format(new Date(2026,i,1)),sales:0,gp:0,count:0}));invoices.forEach(x=>{const m=new Date(x.invoice_date).getMonth();if(months[m]){months[m].sales+=Number(x.revenue||0);months[m].gp+=invoiceGp(x);months[m].count++}});return months}
function ownerChart(invoices=analyticsInvoices()){const series=monthlySeries(invoices),max=Math.max(1,...series.map(x=>x.sales));return `<div class="panel"><div class="section-title"><div><h3>ยอดขาย & กำไรรายเดือน</h3><span class="muted">ข้อมูล Invoice จริง • ${esc(state.reportYear)}</span></div></div><div class="chart-legend"><b>ยอดขาย</b><span>● Gross Profit</span></div><div class="chart">${series.map(x=>{const bar=Math.max(2,Math.round(x.sales/max*175)),gp=x.sales?Math.max(0,Math.min(100,Math.round(x.gp/x.sales*100))):0;return `<div class="chart-col" title="${esc(x.label)} • Sales ${money(x.sales)} • GP ${money(x.gp)}"><div class="chart-value">${x.sales?compactMoney(x.sales).replace('฿',''):''}</div><div class="chart-bar" style="--bar:${bar}px"><div class="chart-gp" style="--gp:${gp}%"></div></div><div class="chart-label">${esc(x.label)}</div></div>`}).join('')}</div><p class="muted">แท่งเต็ม = Sales • แท่งเข้ม = GP</p></div>`}
function customerProfitRows(invoices=analyticsInvoices()){const map=new Map();invoices.forEach(i=>{const k=i.customer_id,r=map.get(k)||{sales:0,gp:0,count:0};r.sales+=Number(i.revenue||0);r.gp+=invoiceGp(i);r.count++;map.set(k,r)});return [...map].map(([id,v])=>({id,name:customerName(id),...v,pct:v.sales?v.gp/v.sales*100:0})).sort((a,b)=>b.gp-a.gp)}
function productSalesRows(invoices=analyticsInvoices()){const allowed=new Set(invoices.map(i=>invoiceOrderId(i.id)).filter(Boolean)),map=new Map();state.data.orderLines.filter(l=>allowed.has(l.order_id)).forEach(l=>{const p=product(l.product_id),key=p.group_code||String(p.code||'อื่น').slice(0,3)||'อื่น',v=map.get(key)||0;map.set(key,v+Number(l.qty||0)*Number(l.unit_price||0))});return [...map].map(([name,sales])=>({name,sales})).sort((a,b)=>b.sales-a.sales)}
function metricBars(rows,valueKey,labelKey){const max=Math.max(1,...rows.map(x=>Math.abs(x[valueKey])));return `<div class="metric-list">${rows.slice(0,5).map(x=>`<div class="metric-line"><span>${esc(x[labelKey])}</span><b>${compactMoney(x[valueKey])}</b><div class="progress"><span style="width:${Math.max(3,Math.round(Math.abs(x[valueKey])/max*100))}%"></span></div></div>`).join('')||empty()}</div>`}

function dashboardPage(){
  const revenue=state.data.invoices.reduce((s,x)=>s+Number(x.revenue||0),0),gp=state.data.invoices.reduce((s,x)=>s+Number(x.revenue||0)-Number(x.product_cost||0)-Number(x.freight_cost||0)-Number(x.other_cost||0),0),open=state.data.orders.filter(x=>!['DELIVERED','CANCELLED'].includes(x.status)).length,stock=state.data.balances.reduce((s,x)=>s+Number(x.on_hand||0),0);
  const recent=state.data.orders.slice(0,8).map(o=>`<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(customerName(o.customer_id))}</td><td>${dmy(o.order_date)}</td><td>${badge(o.status)}</td><td class="num" data-sort="${orderLines(o.id).reduce((s,l)=>s+Number(l.qty),0)}">${qty(orderLines(o.id).reduce((s,l)=>s+Number(l.qty),0))}</td></tr>`);
  if(can('ADMIN')&&state.page==='dashboard'){const pending=state.data.accessRequests.filter(x=>x.status==='PENDING').length,today=new Date().toISOString().slice(0,10),todayOrders=state.data.orders.filter(x=>String(x.order_date).slice(0,10)===today).length;return head('Admin Control Center','ควบคุมข้อมูล ผู้ใช้ และการตั้งค่าระบบ')+cards([['Orders วันนี้',nf.format(todayOrders),'รายการ'],['คลังสินค้า',nf.format(state.data.warehouses.length),'คลัง'],['Users',nf.format(state.data.users.length),'บัญชี'],['รออนุมัติ',nf.format(pending),'คำขอ']])+`<div class="split"><div class="panel"><h3>งานที่ต้องติดตาม</h3><div class="analytics-alert"><strong>${pending} ผู้ใช้รออนุมัติ</strong><button class="btn small-btn" data-go="users">เปิด</button></div><div class="analytics-alert"><strong>${open} Orders ยังไม่ปิด</strong><button class="btn small-btn" data-go="orders">เปิด</button></div><div class="analytics-alert"><strong>${state.data.trips.filter(x=>x.status!=='COMPLETED').length} เที่ยวส่งยังไม่เสร็จ</strong><button class="btn small-btn" data-go="delivery">เปิด</button></div></div><div class="panel"><h3>ทางลัด Admin</h3><div class="tabs"><button class="tab-pill" data-go="masters">Master Data</button><button class="tab-pill" data-go="settings">Business Rules</button><button class="tab-pill" data-go="reports">Reports</button><button class="tab-pill" data-go="executive">Executive Dashboard</button>${state.isPlatformAdmin?'<button class="tab-pill" data-go="commercial">Commercial Control</button>':''}</div></div></div><div class="panel"><h3>Orders ล่าสุด</h3>${table(['Order','ลูกค้า','วันที่','สถานะ','จำนวน'],recent)}</div>`}
  if(!can('OWNER')&&state.page!=='executive')return head('ภาพรวมวันนี้','ข้อมูลจริงจากฐานข้อมูล FlowStock')+cards([['Sales',money(revenue),'Invoice ทั้งหมด'],['Gross Profit',money(gp),revenue?`GP ${(gp/revenue*100).toFixed(2)}%`:'' ],['Open Orders',nf.format(open),'รายการที่ยังไม่ปิด'],['Stock On Hand',qty(stock),'ทุกคลัง']])+`<div class="panel"><h3>Orders ล่าสุด</h3>${table(['Order','ลูกค้า','วันที่','สถานะ','จำนวน'],recent)}</div>`;
  const inv=analyticsInvoices(),filteredBalances=analyticsBalances(),filteredTrips=analyticsTrips(),sales=inv.reduce((s,x)=>s+Number(x.revenue||0),0),profit=inv.reduce((s,x)=>s+invoiceGp(x),0),stockValue=filteredBalances.reduce((s,b)=>{const costs=state.data.costs.filter(c=>c.product_id===b.product_id).sort((a,z)=>String(z.cost_month).localeCompare(String(a.cost_month)));return s+Number(b.on_hand||0)*Number(costs[0]?.unit_cost||0)},0),waiting=state.data.orders.filter(x=>x.status==='WAITING_LOGISTICS'&&(state.reportWarehouse==='ALL'||orderLines(x.id).some(l=>l.warehouse_id===state.reportWarehouse))).length,late=filteredTrips.filter(x=>x.status!=='COMPLETED'&&x.planned_end&&new Date(x.planned_end)<new Date()).length,low=filteredBalances.filter(x=>Number(x.on_hand||0)<=0).length,lowGp=inv.filter(x=>Number(x.revenue)>0&&invoiceGp(x)/Number(x.revenue)*100<12).length,freightVariance=inv.reduce((s,x)=>s+Number(x.freight_cost||0),0)-filteredTrips.reduce((s,t)=>s+Number(t.standard_freight||0),0);
  const alerts=[[`🚚 ${waiting} Orders ยังไม่มีรถ`,'deliveryperformance'],[`⏱ ${late} เที่ยวส่งล่าช้า`,'deliveryperformance'],[`📦 ${low} รายการ Stock หมด/ติดศูนย์`,'stockhealth'],[`💸 Freight Actual ต่างจาก Standard ${compactMoney(freightVariance)}`,'costvariance'],[`📉 ${lowGp} Invoice มี GP ต่ำกว่า 12%`,'profit']];
  return head('ภาพรวมธุรกิจ','Owner Dashboard • วันนี้ต้องรู้อะไร',analyticsFilters())+cards([['ยอดขาย',compactMoney(sales),`ปี ${state.reportYear}`],['Gross Profit',compactMoney(profit),inv.some(x=>x.gp_status==='ESTIMATED')?'Estimated/Final แยกชัดเจน':'Final'],['GP %',sales?(profit/sales*100).toFixed(2)+'%':'0.00%','จาก Invoice'],['Stock Value',compactMoney(stockValue),state.reportWarehouse==='ALL'?`${state.data.warehouses.length} คลัง`:'คลังที่เลือก']])+`<div class="panel"><h3>สิ่งที่ต้องรู้วันนี้</h3>${alerts.map(a=>`<div class="analytics-alert"><strong>${esc(a[0])}</strong><button class="btn small-btn" data-go="${a[1]}">ดู</button></div>`).join('')}</div>${ownerChart(inv)}<div class="split"><div class="panel"><h3>ยอดขายตามกลุ่มสินค้า</h3>${metricBars(productSalesRows(inv),'sales','name')}</div><div class="panel"><h3>Top Customer Profit</h3>${metricBars(customerProfitRows(inv),'gp','name')}</div></div>`;
}
function ordersPage(){
  const q=state.search,rows=state.data.orders.filter(o=>`${o.order_no} ${customerName(o.customer_id)} ${o.status}`.toLowerCase().includes(q)).map(o=>{const ls=orderLines(o.id),amount=ls.reduce((s,l)=>s+Number(l.qty)*Number(l.unit_price),0);return `<tr><td><b>${esc(o.order_no)}</b></td><td>${esc(customerName(o.customer_id))}</td><td>${dmy(o.order_date)}</td><td>${badge(o.status)}</td><td class="num" data-sort="${amount}">${money(amount)}</td><td><button class="btn small-btn" data-action="viewOrder" data-id="${o.id}">เปิด</button></td></tr>`});
  return head('Orders','สร้างและติดตามคำสั่งขาย',`${can('SALES','ADMIN')?'<button class="btn primary" data-action="newOrder">+ สร้าง Order</button>':''}<button class="btn" data-action="exportOrders">ดาวน์โหลด CSV</button>`)+`<div class="toolbar"><input id="pageSearch" placeholder="ค้นหา Order / ลูกค้า / สถานะ"></div><div class="panel">${table(['Order','ลูกค้า','วันที่','สถานะ','มูลค่า',''],rows)}</div>`;
}
function customersPage(){const rows=state.data.customers.filter(x=>`${x.code} ${x.name} ${x.region}`.toLowerCase().includes(state.search)).map(x=>`<tr><td><b>${esc(x.code)}</b></td><td>${esc(x.name)}</td><td>${esc(x.region||'-')}</td><td>${x.active?badge('ACTIVE'):badge('INACTIVE')}</td></tr>`);return head('ลูกค้า','ข้อมูลลูกค้าในบริษัท')+`<div class="toolbar"><input id="pageSearch" placeholder="ค้นหาลูกค้า"></div><div class="panel">${table(['รหัส','ชื่อลูกค้า','ภูมิภาค','สถานะ'],rows)}</div>`}
