function stockHealthPage(){const balances=analyticsBalances(),totalQty=balances.reduce((s,x)=>s+Number(x.on_hand||0),0),zero=balances.filter(x=>Number(x.on_hand||0)<=0),allowedWarehouses=state.reportWarehouse==='ALL'?state.data.warehouses:state.data.warehouses.filter(w=>w.id===state.reportWarehouse),allowedCounts=new Set(state.data.counts.filter(c=>state.reportWarehouse==='ALL'||c.warehouse_id===state.reportWarehouse).map(c=>c.id)),variance=state.data.countLines.filter(x=>allowedCounts.has(x.count_id)).reduce((s,x)=>s+Number(x.count_qty||0)-Number(x.book_qty||0),0),whRows=allowedWarehouses.map(w=>({name:`${w.code} • ${w.name}`,qty:balances.filter(b=>b.warehouse_id===w.id).reduce((s,b)=>s+Number(b.on_hand||0),0)})).sort((a,b)=>b.qty-a.qty),alertRows=zero.map(b=>`<tr><td><b>${esc(product(b.product_id).code||'-')}</b> ${esc(product(b.product_id).name||'')}</td><td>${esc(warehouse(b.warehouse_id).code||'-')}</td><td class="num negative">${qty(b.on_hand)}</td><td>${badge('INACTIVE')}</td></tr>`);return head('Stock Health','มูลค่า • Stock ต่ำ • Slow Moving • No Movement • ตรวจนับ',analyticsFilters({year:false}))+cards([['Stock On Hand',qty(totalQty),state.reportWarehouse==='ALL'?'ทุกคลัง':'คลังที่เลือก'],['Stock หมด/ติดศูนย์',nf.format(zero.length),'รายการ'],['คลังสินค้า',nf.format(allowedWarehouses.length),'คลัง'],['Count Variance',qty(variance),'จำนวนสุทธิ']])+`<div class="split"><div class="panel"><h3>Stock Alert</h3>${table(['สินค้า','คลัง','คงเหลือ','สถานะ'],alertRows)}</div><div class="panel"><h3>Stock ตามคลัง</h3>${metricBars(whRows,'qty','name')}</div></div><div class="panel"><button class="btn" data-go="stock">เปิด Stock Movement</button> <button class="btn" data-go="counts">เปิดรอบตรวจนับ Stock</button></div>`}

function deliveryPerformancePage(){const trips=analyticsTrips(),tripIds=new Set(trips.map(x=>x.id)),completed=trips.filter(x=>x.status==='COMPLETED'),late=trips.filter(x=>x.status!=='COMPLETED'&&x.planned_end&&new Date(x.planned_end)<new Date()),issued=state.data.tripLines.filter(x=>tripIds.has(x.trip_id)).reduce((s,x)=>s+Number(x.issued_qty||0),0),freight=analyticsInvoices().reduce((s,x)=>s+Number(x.freight_cost||0),0),vendorMap=new Map();trips.forEach(t=>{const name=t.transport_supplier_id?(byId('suppliers',t.transport_supplier_id)?.name||'Vendor'):'รถบริษัท',v=vendorMap.get(name)||{name,trips:0,freight:0};v.trips++;v.freight+=Number(t.actual_freight??t.standard_freight??0);vendorMap.set(name,v)});const waiting=state.data.orders.filter(x=>x.status==='WAITING_LOGISTICS'&&(state.reportWarehouse==='ALL'||orderLines(x.id).some(l=>l.warehouse_id===state.reportWarehouse))).length,vendorRows=[...vendorMap.values()].map(x=>`<tr><td><b>${esc(x.name)}</b></td><td class="num">${nf.format(x.trips)}</td><td class="num">${money(x.freight)}</td></tr>`);return head('Delivery Performance','รถบริษัท + รถจ้าง • ต้นทุน • On-time • Loss',analyticsFilters())+cards([['Completed',nf.format(completed.length),'Trips'],['Trips ทั้งหมด',nf.format(trips.length),'รายการ'],['Freight / Unit',issued?money(freight/issued):money(0),'ตามจำนวนส่ง'],['ส่งล่าช้า',nf.format(late.length),'ต้องติดตาม']])+`<div class="split"><div class="panel"><h3>Transport Vendor</h3>${table(['Vendor','Trips','Freight'],vendorRows)}</div><div class="panel"><h3>รายการต้องติดตาม</h3><div class="analytics-alert"><strong>${late.length} เที่ยวล่าช้า</strong><button class="btn small-btn" data-go="delivery">เปิดงาน</button></div><div class="analytics-alert"><strong>${waiting} Order ยังไม่มีรถ</strong><button class="btn small-btn" data-go="delivery">จัดรถ</button></div></div></div>`}

function costVariancePage(){const inv=analyticsInvoices(),productCost=inv.reduce((s,x)=>s+Number(x.product_cost||0),0),actualFreight=inv.reduce((s,x)=>s+Number(x.freight_cost||0),0),other=inv.reduce((s,x)=>s+Number(x.other_cost||0),0),standard=analyticsTrips().reduce((s,t)=>s+Number(t.standard_freight||0),0),variance=actualFreight-standard,rows=[['Freight',standard,actualFreight,variance],['Product Cost',productCost,productCost,0],['Other Cost',other,other,0]].map(x=>`<tr><td><b>${x[0]}</b></td><td class="num">${money(x[1])}</td><td class="num">${money(x[2])}</td><td class="num ${x[3]>0?'negative':x[3]<0?'positive':''}">${x[3]>0?'+':''}${money(x[3])}</td></tr>`);return head('Cost & Variance','หาสาเหตุที่ทำให้กำไรลด',analyticsFilters())+cards([['Product Cost',compactMoney(productCost),'Actual'],['Freight',compactMoney(actualFreight),`เทียบ Standard ${compactMoney(standard)}`],['Other Cost',compactMoney(other),'Actual'],['Freight Variance',compactMoney(variance),variance>0?'สูงกว่า Standard':'ไม่เกิน Standard']])+`<div class="panel"><h3>Variance ที่ควรรู้</h3>${table(['ประเภท','Standard','Actual','Variance'],rows)}</div>`}

