const actions={
  newOrder(){orderModal()},viewOrder(id){viewOrder(id)},newReceipt(){receiptModal()},issueOrder(id){issueModal(id)},newCount(){countModal()},newTransfer(){transferModal()},receiveTransfer(id){receiveTransferModal(id)},newTrip(id){tripModal(id)},completeTrip(id){completeTripModal(id)},openPod(id){openPod(id)},manageMaster(id){masterModal(id)},approveUser(id){approveUser(id)},rejectUser(id){rejectUser(id)},saveUser(id){const b=document.querySelector(`[data-action="saveUser"][data-id="${id}"]`);saveUser(id,b?.dataset.active==='1')},toggleUser(id){const b=document.querySelector(`[data-action="toggleUser"][data-id="${id}"]`);saveUser(id,b?.dataset.active!=='1')},openCustomerProfit(id){state.reportCustomer=id;state.profitView='invoice';state.page='profit';state.search='';renderNav();render()},closeNewPeriod(){setPeriod($('#newPeriodMonth').value+'-01','CLOSED')},togglePeriod(id){const b=document.querySelector(`[data-action="togglePeriod"][data-id="${id}"]`);if(b?.dataset.status==='OPEN')setPeriod(id,'CLOSED');else reopenPeriod(id)},exportOrders(){exportOrders()},exportStock(){exportStock()},exportProfit(){exportProfit()},exportAudit(){exportAudit()},printReport(){window.print()},newTenant(){tenantModal()},manageTenant(id){manageTenantModal(id)}
};
function option(list,label,val='id'){return state.data[list].filter(x=>x.active!==false).map(x=>`<option value="${x[val]}">${esc(label(x))}</option>`).join('')}
function orderLineHtml(){return `<div class="line-editor order-line"><label>สินค้า<select class="ol-product">${option('products',x=>`${x.code} • ${x.name}`)}</select></label><label>คลัง<select class="ol-wh">${option('warehouses',x=>`${x.code} • ${x.name}`)}</select></label><label>จำนวน<input class="ol-qty" type="number" min="0.0001" step="any" required></label><label>ราคา/หน่วย<input class="ol-price" type="number" min="0" step="any" required></label><button type="button" class="btn danger remove-line">ลบ</button></div>`}
function wireLines(kind){const area=$(`#${kind}Lines`);area.querySelectorAll('.remove-line').forEach(b=>b.onclick=()=>{if(area.children.length>1)b.parentElement.remove()});if(kind==='order')area.querySelectorAll('select,input').forEach(el=>el.onchange=updateOrderStock)}
function orderModal(){modal(`<h2>สร้าง Order</h2><p class="muted">รองรับหลายสินค้า ระบบเตือน Stock แต่ยังสร้าง Order ได้</p><form id="orderForm"><div class="form"><label>ลูกค้า<select id="oCustomer" required>${option('customers',x=>`${x.code} • ${x.name}`)}</select></label><label>วันที่ Order<input id="oDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>กำหนดส่ง<input id="oDelivery" type="datetime-local" value="${localInput(86400000)}"></label></div><h3>รายการสินค้า</h3><div id="orderLines">${orderLineHtml()}</div><button type="button" id="addOrderLine" class="btn">+ เพิ่มสินค้า</button><div id="orderStockNote" class="alert warn"></div><div class="actions" style="margin-top:18px"><button class="btn primary" type="submit">ยืนยัน Order</button><button id="cancelOrder" class="btn" type="button">ยกเลิก</button></div></form>`);$('#addOrderLine').onclick=()=>{$('#orderLines').insertAdjacentHTML('beforeend',orderLineHtml());wireLines('order');updateOrderStock()};$('#cancelOrder').onclick=closeModal;wireLines('order');updateOrderStock();$('#orderForm').onsubmit=saveOrder}
function updateOrderStock(){const notes=$$('.order-line').map(r=>{const p=r.querySelector('.ol-product').value,w=r.querySelector('.ol-wh').value,q=Number(r.querySelector('.ol-qty').value||0),a=stockAvailable(p,w);return `${product(p).code||''} / ${warehouse(w).code||''}: Available ${qty(a)}${q>a?` • ขาด ${qty(q-a)}`:''}`});$('#orderStockNote').innerHTML=notes.join('<br>')}
async function saveOrder(e){e.preventDefault();const lines=$$('.order-line').map(r=>({product_id:r.querySelector('.ol-product').value,warehouse_id:r.querySelector('.ol-wh').value,qty:Number(r.querySelector('.ol-qty').value),unit_price:Number(r.querySelector('.ol-price').value)})),delivery=$('#oDelivery').value;if(lines.some(x=>!x.qty||x.unit_price<0))return toast('กรอกจำนวนและราคาให้ครบ',true);await runRpc('create_order',{p_customer_id:$('#oCustomer').value,p_order_date:$('#oDate').value,p_requested_delivery_at:delivery?new Date(delivery).toISOString():null,p_lines:lines,p_request_id:requestId('ORDER')},r=>`สร้าง ${r.order_no} สำเร็จ`)}
function viewOrder(id){const o=byId('orders',id),rows=orderLines(id).map(l=>`<tr><td>${esc(product(l.product_id).code)} ${esc(product(l.product_id).name)}</td><td>${esc(warehouse(l.warehouse_id).code)}</td><td class="num">${qty(l.qty)}</td><td class="num">${qty(l.issued_qty)}</td><td class="num">${money(l.unit_price)}</td><td class="num">${money(Number(l.qty)*Number(l.unit_price))}</td></tr>`);modal(`<h2>${esc(o.order_no)}</h2><p>${esc(customerName(o.customer_id))} • ${badge(o.status)}</p>${table(['สินค้า','คลัง','Order Qty','Issued','ราคา','มูลค่า'],rows)}`)}
function receiptLineHtml(){return `<div class="line-editor receipt-line"><label>สินค้า<select class="gr-product">${option('products',x=>`${x.code} • ${x.name}`)}</select></label><label>จำนวน<input class="gr-qty" type="number" min="0.0001" step="any" required></label><label>Unit Cost<input class="gr-cost" type="number" min="0" step="any"></label><span></span><button type="button" class="btn danger remove-line">ลบ</button></div>`}
function receiptModal(){modal(`<h2>รับสินค้าเข้าคลัง</h2><form id="receiptForm"><div class="form"><label>คลัง<select id="grWh">${option('warehouses',x=>`${x.code} • ${x.name}`)}</select></label><label>Vendor<select id="grSupplier"><option value="">— ไม่ระบุ —</option>${option('suppliers',x=>`${x.code} • ${x.name}`)}</select></label><label>เอกสารอ้างอิง<input id="grRef" required></label><label>วันที่รับ<input id="grDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></label></div><h3>รายการสินค้า</h3><div id="receiptLines">${receiptLineHtml()}</div><button type="button" id="addReceiptLine" class="btn">+ เพิ่มสินค้า</button><div class="actions" style="margin-top:18px"><button class="btn primary">ยืนยันรับสินค้า</button></div></form>`);$('#addReceiptLine').onclick=()=>{$('#receiptLines').insertAdjacentHTML('beforeend',receiptLineHtml());wireLines('receipt')};wireLines('receipt');$('#receiptForm').onsubmit=async e=>{e.preventDefault();const lines=$$('.receipt-line').map(r=>({product_id:r.querySelector('.gr-product').value,qty:Number(r.querySelector('.gr-qty').value),unit_cost:r.querySelector('.gr-cost').value||null}));if(lines.some(x=>!x.qty||x.qty<=0))return toast('กรอกจำนวนรับให้ครบและมากกว่า 0',true);await runRpc('post_goods_receipt',{p_warehouse_id:$('#grWh').value,p_supplier_id:$('#grSupplier').value||null,p_source_doc_no:$('#grRef').value.trim(),p_receipt_date:$('#grDate').value,p_lines:lines,p_request_id:requestId('GR')},r=>`รับสินค้า ${r.gr_no} สำเร็จ`)}}
function issueModal(id){const o=byId('orders',id),rows=orderLines(id).filter(l=>Number(l.qty)>Number(l.issued_qty)).map(l=>`<div class="line-editor issue-line" data-id="${l.id}"><label>สินค้า<input value="${esc(product(l.product_id).code)} • ${esc(product(l.product_id).name)}" disabled></label><label>Available<input value="${qty(stockAvailable(l.product_id,l.warehouse_id))}" disabled></label><label>คงเหลือต้องจ่าย<input value="${qty(Number(l.qty)-Number(l.issued_qty))}" disabled></label><label>จ่ายครั้งนี้<input class="issue-qty" type="number" min="0.0001" max="${Number(l.qty)-Number(l.issued_qty)}" step="any" value="${Math.min(Number(l.qty)-Number(l.issued_qty),stockAvailable(l.product_id,l.warehouse_id))}" required></label></div>`).join('');modal(`<h2>จ่ายสินค้า ${esc(o.order_no)}</h2><div class="alert warn">ระบบห้าม Stock ติดลบ หากของไม่พอสามารถจ่ายบางส่วนได้</div><form id="issueForm">${rows}<div class="actions"><button class="btn primary">ยืนยันตัด Stock</button></div></form>`);$('#issueForm').onsubmit=async e=>{e.preventDefault();const lines=$$('.issue-line').map(r=>({order_line_id:r.dataset.id,qty:Number(r.querySelector('.issue-qty').value)})).filter(x=>x.qty>0);await runRpc('issue_order',{p_order_id:id,p_lines:lines,p_request_id:requestId('ISSUE')},r=>`จ่ายสินค้าแล้ว • ${statusThai[r.status]||r.status}`)}}
function countModal(){modal(`<h2>ตรวจนับ Stock</h2><form id="countForm"><div class="form"><label>คลัง<select id="countWh">${option('warehouses',x=>`${x.code} • ${x.name}`)}</select></label></div><div class="alert warn">กรอกจำนวนที่นับจริง ระบบจะแสดงยอดตามบัญชีและส่วนต่าง</div><div id="countLines"></div><button class="btn primary">ยืนยันผลตรวจนับ</button></form>`);const renderLines=()=>{const wid=$('#countWh').value;$('#countLines').innerHTML=state.data.products.filter(x=>x.active!==false).map(p=>{const book=state.data.balances.find(b=>b.warehouse_id===wid&&b.product_id===p.id)?.on_hand||0;return `<div class="line-editor count-line" data-id="${p.id}" data-book="${book}"><label>สินค้า<input value="${esc(p.code)} • ${esc(p.name)}" disabled></label><label>Book Qty<input value="${qty(book)}" disabled></label><label>Count Qty<input class="count-qty" type="number" min="0" step="any" value="${book}" required></label><label>เหตุผลส่วนต่าง<input class="count-reason" placeholder="บังคับเมื่อมียอดต่าง"></label></div>`}).join('')};$('#countWh').onchange=renderLines;renderLines();$('#countForm').onsubmit=async e=>{e.preventDefault();const lines=$$('.count-line').map(r=>({product_id:r.dataset.id,count_qty:Number(r.querySelector('.count-qty').value),variance_reason:r.querySelector('.count-reason').value.trim()||null}));await runRpc('post_stock_count',{p_warehouse_id:$('#countWh').value,p_lines:lines,p_request_id:requestId('COUNT')},r=>`บันทึก ${r.count_no} สำเร็จ`)}}
function transferModal(){modal(`<h2>สร้างใบโอนคลัง</h2><form id="transferForm"><div class="form"><label>คลังต้นทาง<select id="trFrom">${option('warehouses',x=>`${x.code} • ${x.name}`)}</select></label><label>คลังปลายทาง<select id="trTo">${option('warehouses',x=>`${x.code} • ${x.name}`)}</select></label><label>สินค้า<select id="trProduct">${option('products',x=>`${x.code} • ${x.name}`)}</select></label><label>จำนวนส่ง<input id="trQty" type="number" min="0.0001" step="any" required></label></div><div id="trAvailable" class="alert warn"></div><button class="btn primary">ยืนยันส่งโอน</button></form>`);const update=()=>$('#trAvailable').textContent=`Available ต้นทาง ${qty(stockAvailable($('#trProduct').value,$('#trFrom').value))}`;$('#trFrom').onchange=update;$('#trProduct').onchange=update;update();$('#transferForm').onsubmit=async e=>{e.preventDefault();const from=$('#trFrom').value,to=$('#trTo').value,amount=Number($('#trQty').value);if(from===to)return toast('คลังต้นทางและปลายทางต้องไม่ซ้ำกัน',true);if(amount>stockAvailable($('#trProduct').value,from))return toast('จำนวนโอนมากกว่า Available Stock',true);await runRpc('create_transfer',{p_from_warehouse_id:from,p_to_warehouse_id:to,p_product_id:$('#trProduct').value,p_qty:amount,p_request_id:requestId('TRANSFER')},r=>`สร้าง ${r.transfer_no} สำเร็จ`)}}
function receiveTransferModal(id){const t=byId('transfers',id),l=transferLine(id);modal(`<h2>รับโอน ${esc(t.transfer_no)}</h2><form id="receiveTransferForm"><div class="form"><label>จำนวนส่ง<input value="${qty(l.sent_qty)}" disabled></label><label>จำนวนรับจริง<input id="trReceived" type="number" min="0" max="${l.sent_qty}" step="any" value="${l.sent_qty}" required></label><label class="full">เหตุผลส่วนต่าง<input id="trReason" placeholder="บังคับเมื่อรับไม่เท่าจำนวนส่ง"></label></div><button class="btn primary">ยืนยันรับปลายทาง</button></form>`);$('#receiveTransferForm').onsubmit=async e=>{e.preventDefault();await runRpc('receive_transfer',{p_transfer_id:id,p_received_qty:Number($('#trReceived').value),p_variance_reason:$('#trReason').value.trim()||null,p_request_id:requestId('TRRECV')},r=>`รับ ${r.transfer_no} สำเร็จ • ส่วนต่าง ${qty(r.variance)}`)}}
function tripModal(orderId){const o=byId('orders',orderId);modal(`<h2>จัดรถ ${esc(o.order_no)}</h2><form id="tripForm"><div class="form"><label>รถ<select id="tripVehicle"><option value="">— รถ Vendor / ไม่ระบุ —</option>${option('vehicles',x=>`${x.code} • ${x.plate_no||''} ${x.vehicle_type||''}`)}</select></label><label>คนขับ<select id="tripDriver"><option value="">— ไม่ระบุ —</option>${option('drivers',x=>`${x.code} • ${x.name}`)}</select></label><label>Vendor ขนส่ง<select id="tripVendor"><option value="">— รถบริษัท —</option>${option('suppliers',x=>`${x.code} • ${x.name}`)}</select></label><label>Standard Freight<input id="tripStd" type="number" min="0" step="any" value="0"></label><label>เวลาเริ่ม<input id="tripStart" type="datetime-local" value="${localInput(3600000)}" required></label><label>เวลาสิ้นสุด<input id="tripEnd" type="datetime-local" value="${localInput(14400000)}" required></label></div><button class="btn primary">ยืนยันจัดรถ</button></form>`);$('#tripForm').onsubmit=async e=>{e.preventDefault();const start=new Date($('#tripStart').value),end=new Date($('#tripEnd').value);if(end<=start)return toast('เวลาสิ้นสุดต้องอยู่หลังเวลาเริ่ม',true);await runRpc('create_delivery_trip',{p_order_id:orderId,p_vehicle_id:$('#tripVehicle').value||null,p_driver_id:$('#tripDriver').value||null,p_transport_supplier_id:$('#tripVendor').value||null,p_planned_start:start.toISOString(),p_planned_end:end.toISOString(),p_standard_freight:Number($('#tripStd').value||0),p_request_id:requestId('TRIP')},r=>`จัดรถ ${r.trip_no} สำเร็จ`)}}
function completeTripModal(id){const t=byId('trips',id),lines=tripLines(id).map(l=>`<div class="line-editor pod-line" data-id="${l.id}"><label>สินค้า<input value="${esc(product(l.product_id).code)} • ${esc(product(l.product_id).name)}" disabled></label><label>Warehouse Issue<input value="${qty(l.issued_qty)}" disabled></label><label>ลูกค้ารับจริง<input class="pod-qty" type="number" min="0" max="${l.issued_qty}" step="any" value="${l.issued_qty}" required></label><label>เหตุผลส่วนต่าง<input class="pod-reason" placeholder="Loss / Return / Pending"></label></div>`).join('');modal(`<h2>POD / ปิดงาน ${esc(t.trip_no)}</h2><form id="podForm">${lines}<div class="form"><label>Actual Freight<input id="actualFreight" type="number" min="0" step="any" value="${t.standard_freight||0}" required></label><label>เลขที่ POD<input id="podRef" placeholder="เลขที่เอกสาร (ถ้ามี)"></label><label class="full">ไฟล์ POD (PDF/JPG/PNG ไม่เกิน 10 MB)<input id="podFile" type="file" accept="application/pdf,image/jpeg,image/png" required></label></div><div class="alert warn">ไฟล์เก็บใน Private Storage แยกตามบริษัท Revenue และ Product Cost คำนวณจากจำนวนที่ลูกค้ารับจริง</div><button class="btn primary">อัปโหลด POD และยืนยันส่งสำเร็จ</button></form>`);$('#podForm').onsubmit=e=>completeTrip(e,id)}
const masterMeta={customers:['Customer','code,name,region','รหัส,ชื่อ,ภูมิภาค'],products:['Product','code,name,base_uom','รหัส,ชื่อ,หน่วย'],warehouses:['Warehouse','code,name','รหัส,ชื่อ'],suppliers:['Vendor','code,name,supplier_type','รหัส,ชื่อ,ประเภท'],vehicles:['Vehicle','code,plate_no,vehicle_type','รหัส,ทะเบียน,ประเภทรถ'],drivers:['Driver','code,name,phone','รหัส,ชื่อ,โทรศัพท์']};
function masterModal(kind){if(kind==='costs')return costModal();const [title,fields,labels]=masterMeta[kind],fs=fields.split(','),ls=labels.split(','),rows=state.data[kind].map(x=>`<tr>${fs.map(f=>`<td>${esc(x[f]||'-')}</td>`).join('')}<td>${x.active===false?'ปิด':'ใช้งาน'}</td></tr>`);modal(`<h2>${title}</h2><form id="masterForm"><div class="form">${fs.map((f,i)=>`<label>${ls[i]}<input data-field="${f}" required></label>`).join('')}</div><button class="btn primary" style="margin:16px 0">+ เพิ่ม ${title}</button></form>${table([...ls,'สถานะ'],rows)}`);$('#masterForm').onsubmit=async e=>{e.preventDefault();const obj={company_id:state.profile.company_id,active:true};$$('#masterForm [data-field]').forEach(x=>obj[x.dataset.field]=x.value.trim());const {error}=await db.from(kind).insert(obj);if(error)return fail(error);toast(`เพิ่ม ${title} แล้ว`);closeModal();await loadData();render()}}
function costModal(){const rows=state.data.costs.map(x=>`<tr><td>${esc(product(x.product_id).code)}</td><td>${dmy(x.cost_month)}</td><td class="num">${money(x.unit_cost)}</td><td>${x.locked?'ล็อก':'เปิด'}</td></tr>`);modal(`<h2>Monthly Product Cost</h2><form id="costForm"><div class="form"><label>สินค้า<select id="costProduct">${option('products',x=>`${x.code} • ${x.name}`)}</select></label><label>เดือน<input id="costMonth" type="month" value="${new Date().toISOString().slice(0,7)}" required></label><label>Unit Cost<input id="unitCost" type="number" min="0" step="any" required></label></div><button class="btn primary" style="margin:16px 0">บันทึก Cost</button></form>${table(['สินค้า','เดือน','Unit Cost','สถานะ'],rows)}`);$('#costForm').onsubmit=async e=>{e.preventDefault();const data={company_id:state.profile.company_id,product_id:$('#costProduct').value,cost_month:$('#costMonth').value+'-01',unit_cost:Number($('#unitCost').value)};const {error}=await db.from('monthly_product_costs').upsert(data,{onConflict:'company_id,product_id,cost_month'});if(error)return fail(error);toast('บันทึก Monthly Cost แล้ว');closeModal();await loadData();render()}}
async function forgotPassword(){const email=$('#email').value.trim()||prompt('กรอกอีเมลที่ใช้ใน FlowStock');if(!email)return;setLoading(true);const redirectTo=location.origin+location.pathname;const {error}=await db.auth.resetPasswordForEmail(email,{redirectTo});setLoading(false);if(error)return fail(error);toast('ส่งลิงก์ตั้งรหัสผ่านใหม่แล้ว กรุณาตรวจอีเมล')}
function passwordRecoveryModal(){modal('<h2>ตั้งรหัสผ่านใหม่</h2><form id="recoveryForm"><div class="form"><label class="full">รหัสผ่านใหม่อย่างน้อย 8 ตัวอักษร<input id="recoveryPassword" type="password" minlength="8" required></label></div><button class="btn primary">บันทึกรหัสผ่านใหม่</button></form>');$('#recoveryForm').onsubmit=async e=>{e.preventDefault();setLoading(true);const {error}=await db.auth.updateUser({password:$('#recoveryPassword').value});setLoading(false);if(error)return fail(error);toast('เปลี่ยนรหัสผ่านแล้ว');closeModal()}}
function csvCell(v){const s=String(v??'');return `"${s.replaceAll('"','""')}"`}
function downloadCsv(name,headers,rows){const csv='\ufeff'+[headers,...rows].map(r=>r.map(csvCell).join(',')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportOrders(){downloadCsv('FlowStock_Orders.csv',['Order','Customer','Order Date','Status','Amount THB'],state.data.orders.map(o=>[o.order_no,customerName(o.customer_id),o.order_date,o.status,orderLines(o.id).reduce((s,l)=>s+Number(l.qty)*Number(l.unit_price),0)]))}
function exportStock(){downloadCsv('FlowStock_Stock.csv',['Product Code','Product Name','Warehouse','On Hand','Allocated','Available','UoM'],state.data.balances.map(b=>{const p=product(b.product_id),w=warehouse(b.warehouse_id);return[p.code,p.name,w.code,Number(b.on_hand),Number(b.allocated),Number(b.on_hand)-Number(b.allocated),p.base_uom]}))}
function exportProfit(){downloadCsv('FlowStock_Profit.csv',['Invoice','Date','Customer','Revenue','Product Cost','Freight','Other Cost','Gross Profit','GP %','Status'],state.data.invoices.map(i=>{const gp=Number(i.revenue)-Number(i.product_cost)-Number(i.freight_cost)-Number(i.other_cost);return[i.invoice_no,i.invoice_date,customerName(i.customer_id),i.revenue,i.product_cost,i.freight_cost,i.other_cost,gp,Number(i.revenue)?(gp/Number(i.revenue)*100).toFixed(2):0,i.gp_status]}))}
function exportAudit(){downloadCsv('FlowStock_Audit_Log.csv',['Timestamp','Action','Entity Type','Entity ID','User ID'],(state.data.audit||[]).map(x=>[x.created_at,x.action,x.entity_type,x.entity_id,x.user_id]))}
async function completeTrip(e,id){e.preventDefault();const file=$('#podFile').files[0];if(!file||!['application/pdf','image/jpeg','image/png'].includes(file.type)||file.size>10485760)return toast('เลือกไฟล์ PDF/JPG/PNG ขนาดไม่เกิน 10 MB',true);const ext=({"application/pdf":"pdf","image/jpeg":"jpg","image/png":"png"})[file.type],path=`${state.profile.company_id}/${id}/${crypto.randomUUID()}.${ext}`,lines=$$('.pod-line').map(r=>({trip_line_id:r.dataset.id,received_qty:Number(r.querySelector('.pod-qty').value),variance_reason:r.querySelector('.pod-reason').value.trim()||null}));$('#modalBody').dataset.busy='1';setLoading(true);let completed=false;try{const {error:uploadError}=await db.storage.from('pod-documents').upload(path,file,{contentType:file.type,upsert:false});if(uploadError)throw uploadError;const ref=$('#podRef').value.trim();const {data,error}=await db.rpc('complete_delivery',{p_trip_id:id,p_lines:lines,p_actual_freight:Number($('#actualFreight').value),p_pod_reference:ref?`${ref} | ${path}`:path,p_request_id:requestId('POD')});if(error)throw error;completed=true;const {error:attachError}=await db.rpc('attach_delivery_document',{p_trip_id:id,p_object_path:path,p_original_name:file.name,p_mime_type:file.type,p_file_size:file.size});if(attachError)throw attachError;toast(`ปิดงานและสร้าง ${data.invoice_no} • ${data.gp_status}`);$('#modalBody').dataset.busy='0';closeModal();await loadData();render()}catch(err){if(!completed)await db.storage.from('pod-documents').remove([path]);fail(err)}finally{$('#modalBody').dataset.busy='0';setLoading(false)}}
async function openPod(id){const doc=state.data.deliveryDocs.find(x=>x.id===id);if(!doc)return toast('ไม่พบเอกสาร POD',true);setLoading(true);const {data,error}=await db.storage.from(doc.bucket_id).createSignedUrl(doc.object_path,300);setLoading(false);if(error)return fail(error);window.open(data.signedUrl,'_blank','noopener')}
function tenantModal(){modal(`<h2>เปิดบริษัทลูกค้า</h2><form id="tenantForm"><div class="form"><label>รหัสบริษัท<input id="tenantCode" minlength="3" maxlength="20" pattern="[A-Za-z0-9_-]+" required placeholder="เช่น ACME01"></label><label>ชื่อบริษัท<input id="tenantName" required></label><label>แพ็กเกจ<select id="tenantPlan"><option>STARTER</option><option>BUSINESS</option><option>ENTERPRISE</option></select></label><label>จำนวนผู้ใช้สูงสุด<input id="tenantMax" type="number" min="1" max="10000" value="10" required></label><label>ทดลองใช้ (วัน)<input id="tenantTrial" type="number" min="1" max="365" value="30" required></label></div><div class="alert warn">ระบบจะสร้างรหัสเปิดบริษัทสำหรับ Admin ใช้ได้ครั้งเดียวและหมดอายุใน 7 วัน</div><button class="btn primary">สร้างบริษัท</button></form>`);$('#tenantForm').onsubmit=async e=>{e.preventDefault();setLoading(true);const {data,error}=await db.rpc('platform_create_tenant',{p_code:$('#tenantCode').value,p_name:$('#tenantName').value,p_plan:$('#tenantPlan').value,p_trial_days:Number($('#tenantTrial').value),p_max_users:Number($('#tenantMax').value)});setLoading(false);if(error)return fail(error);await loadData();modal(`<h2>สร้างบริษัท ${esc(data.company_code)} สำเร็จ</h2><div class="alert ok">คัดลอกรหัสด้านล่างส่งให้ Admin บริษัท รหัสจะแสดงครั้งนี้ครั้งเดียว</div><label>รหัสเปิดบริษัท<input id="newTenantCode" value="${esc(data.onboarding_code)}" readonly></label><button id="copyTenantCode" class="btn primary wide">คัดลอกรหัส</button><p class="muted">หมดอายุ ${dmy(data.expires_at)}</p>`);$('#copyTenantCode').onclick=async()=>{await navigator.clipboard.writeText(data.onboarding_code);toast('คัดลอกรหัสแล้ว')}}}
function manageTenantModal(id){const c=state.data.tenants.find(x=>x.id===id);modal(`<h2>จัดการ ${esc(c.code)} • ${esc(c.name)}</h2><form id="tenantManageForm"><div class="form"><label>สถานะ<select id="manageStatus">${['TRIAL','ACTIVE','SUSPENDED','EXPIRED'].map(x=>`<option ${x===c.subscription_status?'selected':''}>${x}</option>`).join('')}</select></label><label>แพ็กเกจ<select id="managePlan">${['STARTER','BUSINESS','ENTERPRISE'].map(x=>`<option ${x===c.subscription_plan?'selected':''}>${x}</option>`).join('')}</select></label><label>จำนวนผู้ใช้สูงสุด<input id="manageMax" type="number" min="1" max="10000" value="${c.max_users}" required></label></div><div class="alert warn">SUSPENDED และ EXPIRED จะหยุดการเข้าถึงข้อมูลและการทำธุรกรรมทันที แต่ไม่ลบข้อมูล</div><button class="btn primary">บันทึก</button></form>`);$('#tenantManageForm').onsubmit=async e=>{e.preventDefault();await runRpc('platform_set_company_status',{p_company_id:id,p_status:$('#manageStatus').value,p_plan:$('#managePlan').value,p_max_users:Number($('#manageMax').value)},()=>`อัปเดต ${c.code} แล้ว`)}}
async function approveUser(id){const role=$(`#approveRole-${id}`).value;setLoading(true);const {data,error}=await db.rpc('approve_access',{p_request_id:id,p_app_role:role});setLoading(false);if(error)return fail(error);toast(`อนุมัติสิทธิ์ ${roleThai[data.role]} แล้ว`);await loadData();render()}
async function rejectUser(id){if(!confirm('ยืนยันปฏิเสธคำขอนี้?'))return;setLoading(true);const {error}=await db.rpc('reject_access',{p_request_id:id});setLoading(false);if(error)return fail(error);toast('ปฏิเสธคำขอแล้ว');await loadData();render()}
async function saveUser(id,active){const role=$(`#userRole-${id}`).value;setLoading(true);const {error}=await db.rpc('admin_update_user',{p_user_id:id,p_app_role:role,p_active:active});setLoading(false);if(error)return fail(error);toast('บันทึกสิทธิ์ผู้ใช้แล้ว');await loadData();render()}
async function setPeriod(date,status,reason=null){if(status==='CLOSED'&&!confirm(`ยืนยันปิดงวด ${date.slice(0,7)}? รายการในงวดนี้จะแก้ไขไม่ได้`))return;setLoading(true);const {error}=await db.rpc('set_period_status',{p_period_month:date,p_status:status,p_reason:reason});setLoading(false);if(error)return fail(error);toast(status==='CLOSED'?'ปิดงวดแล้ว':'เปิดงวดแล้ว');await loadData();render()}
function reopenPeriod(date){modal(`<h2>Reopen Period ${esc(date.slice(0,7))}</h2><form id="reopenForm"><div class="form"><label class="full">เหตุผลที่เปิดงวดใหม่<textarea id="reopenReason" required></textarea></label></div><button class="btn primary">ยืนยัน Reopen</button></form>`);$('#reopenForm').onsubmit=async e=>{e.preventDefault();await setPeriod(date,'OPEN',$('#reopenReason').value.trim());closeModal()}}
async function runRpc(name,args,message){$('#modalBody').dataset.busy='1';setLoading(true);try{const {data,error}=await db.rpc(name,args);if(error)throw error;toast(message(data));$('#modalBody').dataset.busy='0';closeModal();await loadData();render()}catch(e){fail(e)}finally{$('#modalBody').dataset.busy='0';setLoading(false)}}

init().catch(e=>{setLoading(false);showLogin();$('#loginError').textContent=errorText(e);console.error(e)});
